class LoginVm : public QObject {
    Q_OBJECT
    Q_PROPERTY(QString user READ user WRITE setUser NOTIFY userChanged)
public:
    QString user() const { return m_user; }
    void setUser(const QString &u) {
        if (m_user == u) return;              // notify only on real change
        m_user = u; emit userChanged();
    }
signals: void userChanged();
private: QString m_user;
};   // login.qml: TextField { text: vm.user; onAccepted: vm.submit() }

